tool_use_result.content:
"""Greedy template placement, one local day at a time.

For each local day of the week: while some (template, queue) pair still covers at least half an
hour of uncovered requirement, place the best-scoring pair on the available agent with the fewest
hours so far. Breaks go at the shift midpoint unless a client asks for the SOW §2.3 rule. Deterministic:
fixed template order, agent ids as the tie-break.

Client-selectable steps (see configs/defaults.yaml; each is off unless a client file turns it on):
- `floor_first`: a queue with a `min_cover` floor is planned for the whole week before the other queues
  (`_plan_floor_queue`), so the floor is held before daytime demand takes the agents' hours.
- `net_of_breaks`: coverage must hold after breaks; intervals a break leaves short get another agent.
- `trim_surplus`: shifts the week does not need are dropped while nothing gets worse.
- `min_rest_hours`, `split_contracts`: working-time rules applied while placing.
"""
from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field
from datetime import date, datetime, timedelta
from zoneinfo import ZoneInfo

import numpy as np
import pandas as pd

from wfm import constraints
from wfm.ingest.loader import local_days
from wfm.roster import Agent
from wfm.scheduler.templates import Template, eligible, templates_for


@dataclass
class Shift:
    agent_id: str
    queue: str
    template: Template
    day: date
    segments: list[tuple[datetime, datetime]]
    intervals: list[datetime] = field(default_factory=list)   # grid slots the segments cover
    break_start: datetime | None = None
    break_minutes: int = 0

    @property
    def hours(self) -> float:
        return sum((e - s).total_seconds() for s, e in self.segments) / 3600.0


def _covered(segments, day_grid) -> list[datetime]:
    return [t for s, e in segments for t in day_grid if s <= t < e]


MAX_REPAIR_ROUNDS = 60


def schedule_week(req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str) -> list[Shift]:
    """Place the shifts, then the breaks. With `net_of_breaks`, an interval that a break leaves short
    of its requirement gets one more agent to cover it, and the week is placed again, until coverage
    holds net of breaks (SOW §1.2) or the rounds run out. Floor queues are planned first and are not
    repaired this way: a floor they cannot hold is reported, not chased."""
    floor_qs = [q for q in dict.fromkeys(req["queue"]) if (cfg.get("min_cover") or {}).get(q)] \
        if cfg.get("floor_first") else []
    extra: dict[tuple[str, datetime], int] = defaultdict(int)
    for _ in range(MAX_REPAIR_ROUNDS):
        shifts = _schedule_once(req, cfg, agents, week, extra, floor_qs)
        place_breaks(shifts, cfg, req)
        short = [k for k in net_shortfalls(shifts, req) if k[0] not in floor_qs] if cfg.get("net_of_breaks") else []
        if not short:
            break
        for key in short:
            extra[key] += 1
    if cfg.get("trim_surplus") and cfg.get("net_of_breaks"):
        shifts = trim_surplus(shifts, req, cfg, agents)
    return shifts


def _schedule_once(req, cfg, agents, week, extra, floor_qs) -> list[Shift]:
    shifts: list[Shift] = []
    for q in floor_qs:
        shifts += _plan_floor_queue(req[req["queue"] == q], q, cfg, agents, week, shifts)
    rest = [q for q in dict.fromkeys(req["queue"]) if q not in floor_qs]
    shifts += _place(req[req["queue"].isin(rest)], cfg, agents, week, extra, prior=shifts)
    return shifts


def _tally(shifts: list[Shift], skills: dict[str, frozenset]):
    """Gross agents per (queue, interval), and the agents on another queue who hold that queue's skill."""
    gross: dict[tuple[str, datetime], int] = defaultdict(int)
    cross: dict[tuple[str, datetime], int] = defaultdict(int)
    for sh in shifts:
        for t in sh.intervals:
            gross[(sh.queue, t)] += 1
            for skill in skills.get(sh.agent_id, ()):
                if skill != sh.queue:
                    cross[(skill, t)] += 1
    return gross, cross


def _deficits(shifts: list[Shift], req: pd.DataFrame, cfg: dict, skills: dict[str, frozenset]):
    """(agent-intervals short of the requirement net of breaks, floor gaps). Places the breaks."""
    place_breaks(shifts, cfg, req)
    short = sum(_short_units(shifts, req).values())
    gross, cross = _tally(shifts, skills)
    gaps = 0
    for q, t in zip(req["queue"], req["interval_start_utc"]):
        floor = constraints.floor(q, t, cfg)
        if floor and constraints.cover(gross[(q, t)], cross[(q, t)], cfg) < floor:
            gaps += 1
    return short, gaps


def trim_surplus(shifts: list[Shift], req: pd.DataFrame, cfg: dict, agents: list[Agent]) -> list[Shift]:
    """Drop shifts, most-surplus first, while neither the shortfall nor the floor gaps grow. Removing a
    shift never adds a rule violation, so only coverage and the efficiency bound (SOW §1.6) change."""
    skills = {a.agent_id: a.skills for a in agents}
    required = {(q, t): r for q, t, r in zip(req["queue"], req["interval_start_utc"], req["required"])}
    keep = list(shifts)
    base = _deficits(keep, req, cfg, skills)
    changed = True
    while changed:
        changed = False
        gross, _ = _tally(keep, skills)
        surplus = {id(sh): sum(gross[(sh.queue, t)] - required.get((sh.queue, t), 0) for t in sh.intervals)
                   for sh in keep}
        for sh in sorted(keep, key=lambda s: -surplus[id(s)]):
            cand = [s for s in keep if s is not sh]
            after = _deficits(cand, req, cfg, skills)
            if after[0] <= base[0] + 1e-9 and after[1] <= base[1]:
                keep, base, changed = cand, after, True
    place_breaks(keep, cfg, req)
    return keep


def _short_units(shifts: list[Shift], req: pd.DataFrame) -> dict[tuple[str, datetime], float]:
    """(queue, interval) -> agents short of the requirement, net of the breaks in the interval."""
    gross: dict[tuple[str, datetime], int] = defaultdict(int)
    on_break: dict[tuple[str, datetime], int] = defaultdict(int)
    for sh in shifts:
        for t in sh.intervals:
            gross[(sh.queue, t)] += 1
        if sh.break_start is not None:
            on_break[(sh.queue, sh.break_start)] += 1
    short = {}
    for q, t, r in zip(req["queue"], req["interval_start_utc"], req["required"]):
        net = gross[(q, t)] - on_break[(q, t)]
        if r > net:
            short[(q, t)] = float(r - net)
    return short


def net_shortfalls(shifts: list[Shift], req: pd.DataFrame) -> list[tuple[str, datetime]]:
    """(queue, interval) where agents on the queue, less those on break in the interval, fall short of the
    requirement."""
    return list(_short_units(shifts, req))


def _can_take(a: Agent, tpl: Template, day: date, segs, by_agent, cfg: dict, min_rest: timedelta,
              split_ok, max_run: int) -> bool:
    """May agent `a` take template `tpl` on `day`: contract and skill rules, one template per local day, no
    overlap, the rest period against every other shift of the agent, weekly hours, consecutive days."""
    if not eligible(tpl, a.contract):
        return False
    if tpl.is_split and split_ok is not None and a.contract not in split_ok:
        return False
    mine = by_agent.get(a.agent_id, [])
    if any(sh.day == day for sh in mine):
        return False
    start, end = segs[0][0], segs[-1][1]
    for sh in mine:
        s_start, s_end = sh.segments[0][0], sh.segments[-1][1]
        if s_end <= start:
            gap = start - s_end
        elif end <= s_start:
            gap = s_start - end
        else:
            return False
        if gap < min_rest:
            return False
    if sum(sh.hours for sh in mine) + tpl.hours > cfg["weekly_hours"][a.contract] + 1e-9:
        return False
    return not _would_exceed_run([sh.day for sh in mine], day, max_run)


def _place(req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str, extra, prior=()) -> list[Shift]:
    tz = cfg["tz"]
    grain_h = cfg["interval_minutes"] / 60.0
    max_run = cfg["max_consecutive_days"]
    templates = templates_for(cfg)
    queues = list(dict.fromkeys(req["queue"]))
    min_rest = timedelta(hours=float(cfg.get("min_rest_hours") or 0))
    split_ok = cfg.get("split_contracts")       # contracts that may take a split shift; None = all

    # the requirement, raised where a break left the interval short (see schedule_week)
    required = {q: {t: r + extra.get((q, t), 0) for t, r in zip(g["interval_start_utc"], g["required"])}
                for q, g in req.groupby("queue")}
    cover = {q: defaultdict(int) for q in queues}
    cross = {q: defaultdict(int) for q in queues}    # agents on another queue holding this skill (min_cover)
    grid = sorted(set(req["interval_start_utc"]))
    z = ZoneInfo(tz)
    floors = {q: {t: constraints.floor(q, t, cfg) for t in grid} for q in queues}

    by_agent: dict[str, list[Shift]] = defaultdict(list)   # everything each agent already works
    for sh in prior:
        by_agent[sh.agent_id].append(sh)
    shifts: list[Shift] = []

    for day in local_days(week, tz):
        day_grid = [t for t in grid if t.astimezone(z).date() == day]
        dead: set[tuple[str, str]] = set()   # (template, queue) pairs nobody can take today
        while True:
            best, best_val = None, 0.0
            for tpl in templates:
                segs = tpl.segments_utc(day, tz)
                ivs = _covered(segs, day_grid)
                for q in queues:
                    if (tpl.id, q) in dead:
                        continue
                    val = sum(min(1, constraints.uncovered(required[q][t], floors[q][t], cover[q][t], cross[q][t], cfg))
                              for t in ivs)
                    if val > best_val + 1e-9:
                        best, best_val = (tpl, q, segs, ivs), val
            if best is None or best_val * grain_h < 0.5:
                break
            tpl, q, segs, ivs = best
            cands = [a for a in agents
                     if q in a.skills and _can_take(a, tpl, day, segs, by_agent, cfg, min_rest, split_ok, max_run)]
            if not cands:
                dead.add((tpl.id, q))
                continue
            a = min(cands, key=lambda x: (sum(sh.hours for sh in by_agent[x.agent_id]), x.agent_id))
            sh = Shift(a.agent_id, q, tpl, day, segs, ivs)
            shifts.append(sh)
            by_agent[a.agent_id].append(sh)
            for t in ivs:
                cover[q][t] += 1
                for other in a.skills & set(queues) - {q}:
                    cross[other][t] += 1

    return shifts


def _mixes(n_types: int, max_total: int) -> np.ndarray:
    """Every vector of n_types template counts whose total is at most max_total."""
    out: list[list[int]] = []

    def rec(prefix: list[int], left: int) -> None:
        if len(prefix) == n_types:
            out.append(prefix)
            return
        for c in range(left + 1):
            rec(prefix + [c], left - c)

    rec([], max_total)
    return np.array(out, dtype=int)


def _plan_floor_queue(req_q: pd.DataFrame, q: str, cfg: dict, agents: list[Agent], week: str,
                      prior) -> list[Shift]:
    """Floor-first plan for one queue (SOW §2.6 and the queue's own demand).

    Per local day, every mix of whole-shift templates that holds the floor and the requirement's floor
    in every interval is scored by the requirement intervals it meets. A DP over the week then takes the
    best mixes within the queue's agent-hours. The shifts are assigned to agents under the same rules as the
    greedy (`_can_take`). A shift the rules cannot place is dropped and its interval shows as a gap."""
    tz = cfg["tz"]
    z = ZoneInfo(tz)
    min_rest = timedelta(hours=float(cfg.get("min_rest_hours") or 0))
    max_run = cfg["max_consecutive_days"]
    req_by_t = dict(zip(req_q["interval_start_utc"], req_q["required"]))
    grid = sorted(req_by_t)
    skilled = [a for a in agents if q in a.skills]
    hours_cap = sum(cfg["weekly_hours"][a.contract] for a in skilled)
    tpls = [t for t in templates_for(cfg) if not t.is_split]
    combos = _mixes(len(tpls), len(skilled))
    hrs = np.array([t.hours for t in tpls])

    options_by_day = []
    for day in local_days(week, tz):
        day_grid = [t for t in grid if t.astimezone(z).date() == day]
        if not day_grid:
            options_by_day.append({0.0: (0, np.zeros(len(tpls), dtype=int))})
            continue
        cov = np.zeros((len(tpls), len(day_grid)), dtype=int)
        for k, tp in enumerate(tpls):
            segs = tp.segments_utc(day, tz)
            for i, t in enumerate(day_grid):
                cov[k, i] = any(s <= t < e for s, e in segs)
        need = np.array([max(req_by_t[t], constraints.floor(q, t, cfg)) for t in day_grid], dtype=float)
        req = np.array([req_by_t[t] for t in day_grid], dtype=float)
        covered = combos @ cov
        feasible = (covered >= need).all(axis=1)
        met = ((covered >= req) & (req > 0)).sum(axis=1)
        hours = combos @ hrs
        options: dict[float, tuple[int, np.ndarray]] = {}
        for n in np.nonzero(feasible)[0]:
            h, s = float(hours[n]), int(met[n])
            if h not in options or s > options[h][0]:
                options[h] = (s, combos[n])
        options_by_day.append(options)

    dp: dict[float, tuple[int, list]] = {0.0: (0, [])}
    for options in options_by_day:
        nxt: dict[float, tuple[int, list]] = {}
        for h0, (s0, plan0) in dp.items():
            for h1, (s1, c1) in options.items():
                h = h0 + h1
                if h <= hours_cap + 1e-9 and (h not in nxt or s0 + s1 > nxt[h][0]):
                    nxt[h] = (s0 + s1, plan0 + [c1])
        dp = nxt
    if not dp:
        return []
    _, plan = max(dp.items(), key=lambda kv: (kv[1][0], -kv[0]))[1]

    by_agent: dict[str, list[Shift]] = defaultdict(list)
    for sh in prior:
        by_agent[sh.agent_id].append(sh)
    shifts: list[Shift] = []
    for day, counts in zip(local_days(week, tz), plan):
        day_grid = [t for t in grid if t.astimezone(z).date() == day]
        chosen = [tp for k, tp in enumerate(tpls) for _ in range(int(counts[k]))]
        chosen.sort(key=lambda tp: (-tp.hours, tp.id))
        for tp in chosen:
            segs = tp.segments_utc(day, tz)
            cands = [a for a in skilled if _can_take(a, tp, day, segs, by_agent, cfg, min_rest, None, max_run)]
            if not cands:
                continue
            a = min(cands, key=lambda x: (sum(sh.hours for sh in by_agent[x.agent_id]), x.agent_id))
            sh = Shift(a.agent_id, q, tp, day, segs, _covered(segs, day_grid))
            shifts.append(sh)
            by_agent[a.agent_id].append(sh)
    return shifts


def _would_exceed_run(worked: list[date], day: date, max_run: int) -> bool:
    """True if working `day` would make more than max_run consecutive local days."""
    run = 0
    d = day - timedelta(days=1)
    while d in worked:
        run += 1
        d -= timedelta(days=1)
    return run >= max_run


def place_breaks(shifts: list[Shift], cfg: dict, req: pd.DataFrame) -> None:
    """One break per long shift. `midpoint`: on the covered interval nearest the shift midpoint.
    `surplus` (SOW §2.3): in the window of hours after the shift start, on the planning interval whose
    gross coverage surplus (agents on the queue, ignoring breaks, less the requirement) is largest; a tie
    goes to the earlier interval."""
    rule = cfg["break"]
    length = timedelta(minutes=rule["minutes"])
    surplus_mode = rule.get("placement", "midpoint") == "surplus"
    if surplus_mode:
        lo, hi = rule["window_hours"]
        gross: dict[tuple[str, datetime], int] = defaultdict(int)
        for sh in shifts:
            for t in sh.intervals:
                gross[(sh.queue, t)] += 1
        required = {(q, t): r for q, t, r in zip(req["queue"], req["interval_start_utc"], req["required"])}
    for sh in shifts:
        sh.break_start, sh.break_minutes = None, 0
        if sh.hours < rule["min_shift_hours"]:
            continue
        if surplus_mode:
            start = sh.segments[0][0]
            window = [t for t in sh.intervals
                      if lo <= (t - start).total_seconds() / 3600 <= hi
                      and any(s <= t and t + length <= e for s, e in sh.segments)]
            if window:
                sh.break_start = min(window, key=lambda t: (-(gross[(sh.queue, t)] - required.get((sh.queue, t), 0)), t))
                sh.break_minutes = rule["minutes"]
            continue
        fits = [t for t in sh.intervals if any(s <= t and t + length <= e for s, e in sh.segments)]
        if not fits:
            continue
        mid = sh.segments[0][0] + timedelta(hours=sh.hours / 2)
        sh.break_start = min(fits, key=lambda t: (abs((t - mid).total_seconds()), t))
        sh.break_minutes = rule["minutes"]


def to_frame(shifts: list[Shift]) -> pd.DataFrame:
    """schedule.csv rows: one per segment; the break sits on the segment that contains it."""
    rows = []
    for sh in shifts:
        for i, (s, e) in enumerate(sh.segments):
            has_break = sh.break_start is not None and s <= sh.break_start < e
            rows.append({
                "agent_id": sh.agent_id, "queue": sh.queue,
                "segment_start_utc": s.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "segment_end_utc": e.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "template_id": sh.template.id, "segment_idx": i,
                "break_start_utc": sh.break_start.strftime("%Y-%m-%dT%H:%M:%SZ") if has_break else "",
                "break_minutes": sh.break_minutes if has_break else 0,
            })
    df = pd.DataFrame(rows, columns=["agent_id", "queue", "segment_start_utc", "segment_end_utc",
                                     "template_id", "segment_idx", "break_start_utc", "break_minutes"])
    return df.sort_values(["segment_start_utc", "agent_id", "segment_idx"], kind="stable").reset_index(drop=True)

