arguments.command:
cat > /tmp/check_sow.py <<'EOF'
"""Independent SOW check of a Northwind schedule: reads raw export + roster + schedule.csv, not wfm code
(except nothing). Prints a JSON summary."""
import sys, json, math
from collections import defaultdict
from datetime import datetime, timedelta, timezone, date
from zoneinfo import ZoneInfo
import pandas as pd

WEEK = sys.argv[1]; SCHED = sys.argv[2]; EVAL = sys.argv[3]; EXPORT = sys.argv[4]; ROSTER = sys.argv[5]
TZ = ZoneInfo("America/Chicago")
SLA = {"priority": (0.90, 30), "standard": (0.80, 20), "vip": (0.90, 20)}
CAP = 0.85

# ---- demand, straight from the export (UTC = local label + row offset, snapped to 30 min)
ex = pd.read_csv(EXPORT, dtype=str)
ex["lt"] = pd.to_datetime(ex.interval_start_local).dt.round("30min")
ex["utc"] = [datetime.strptime(l.strftime("%Y-%m-%d %H:%M") + o.replace(":", ""), "%Y-%m-%d %H:%M%z").astimezone(timezone.utc)
             for l, o in zip(ex.lt, ex.utc_offset)]
ex["volume"] = ex.volume.astype(float); ex["aht"] = ex.aht_sec.astype(float)
mon = date.fromisocalendar(int(WEEK[:4]), int(WEEK[-2:]), 1)
start = datetime(mon.year, mon.month, mon.day, tzinfo=TZ); end = start + timedelta(days=7)
grid = []
t = start.astimezone(timezone.utc)
while t < end.astimezone(timezone.utc):
    grid.append(t); t += timedelta(minutes=30)
dem = {(r.queue, r.utc): (r.volume, r.aht) for r in ex.itertuples()}
assert len(dem) == len(ex), "duplicate queue/interval after snapping"

# ---- Erlang C (own implementation)
def erlang_c(A, n):
    # Erlang B by recursion, then Erlang C
    B = 1.0
    for k in range(1, n + 1):
        B = A * B / (k + A * B)
    return n * B / (n - A * (1 - B))
def sl(A, n, aht, tgt):
    if n <= A: return 0.0
    return 1 - erlang_c(A, n) * math.exp(-(n - A) * tgt / aht)
req = {}
for (q, u), (v, aht) in dem.items():
    if v <= 0: req[(q, u)] = 0; continue
    A = v / 1800 * aht
    tgt_sl, tgt_s = SLA[q]
    n = max(1, math.ceil(A / CAP))
    while not (sl(A, n, aht, tgt_s) >= tgt_sl and A / n <= CAP): n += 1
    req[(q, u)] = n
for q in SLA:
    for u in grid: req.setdefault((q, u), 0)
req_hours = sum(req.values()) * 0.5

# ---- schedule
sc = pd.read_csv(SCHED, dtype=str)
sc["s"] = pd.to_datetime(sc.segment_start_utc, utc=True); sc["e"] = pd.to_datetime(sc.segment_end_utc, utc=True)
sc["brk"] = pd.to_datetime(sc.break_start_utc.replace("", None), utc=True)
sc["bm"] = sc.break_minutes.fillna("0").astype(int)
ro = pd.read_csv(ROSTER, dtype=str); ro = {r.agent_id: (r.contract, set(r.skills.split(";"))) for r in ro.itertuples()}
sc["ld"] = sc.s.dt.tz_convert(TZ).dt.date
problems = defaultdict(list)
hrs_total = float(((sc.e - sc.s).dt.total_seconds() / 3600).sum())
for r in sc.itertuples():
    contract, skills = ro[r.agent_id]
    if r.queue not in skills: problems["skill"].append(r.agent_id)
    if r.s.astimezone(TZ).date() != (r.e - timedelta(seconds=1)).astimezone(TZ).date(): problems["crosses_midnight"].append(r.agent_id)
    if r.s.astimezone(TZ).hour < 6: problems["before_0600"].append(r.agent_id)
shifts = []
for (aid, tpl, ld), g in sc.groupby(["agent_id", "template_id", "ld"]):
    g = g.sort_values("s")
    shifts.append(dict(agent=aid, q=g.queue.iloc[0], tpl=tpl, day=ld, segs=list(zip(g.s, g.e)),
                       hours=float(((g.e - g.s).dt.total_seconds() / 3600).sum()), brk=g[g.bm > 0]))
for aid in ro:
    mine = sorted([s for s in shifts if s["agent"] == aid], key=lambda s: s["segs"][0][0])
    contract = ro[aid][0]
    if sum(s["hours"] for s in mine) > (40 if contract == "FT" else 24) + 1e-9: problems["weekly_hours"].append(aid)
    for a, b in zip(mine, mine[1:]):
        gap = b["segs"][0][0] - a["segs"][-1][1]
        if gap < timedelta(hours=11): problems["rest"].append((aid, str(a["day"]), str(b["day"])))
    if len({s["day"] for s in mine}) != len(mine): problems["two_shifts_one_day"].append(aid)
    days = sorted({s["day"] for s in mine}); run = 1; worst = 1
    for d1, d2 in zip(days, days[1:]):
        run = run + 1 if (d2 - d1).days == 1 else 1; worst = max(worst, run)
    if worst > 5: problems["consecutive_days"].append(aid)
    for s in mine:
        if len(s["segs"]) > 1 and contract != "PT": problems["split_not_PT"].append(aid)
        segs = sorted(s["segs"])
    ss = sorted([seg for s in mine for seg in s["segs"]])
    for x, y in zip(ss, ss[1:]):
        if y[0] < x[1]: problems["overlap"].append(aid)
    # breaks
    for s in mine:
        need_break = s["hours"] >= 6
        if need_break:
            if len(s["brk"]) != 1 or int(s["brk"].bm.iloc[0]) != 20: problems["break_count"].append((aid, str(s["day"])))
            else:
                b = s["brk"].brk.iloc[0]; first = s["segs"][0][0]
                off = (b - first).total_seconds() / 3600
                if not (2 <= off <= 5): problems["break_window"].append((aid, str(s["day"]), off))
                if not any(st <= b and b + timedelta(minutes=20) <= en for st, en in s["segs"]): problems["break_outside"].append(aid)
        elif len(s["brk"]): problems["break_short_shift"].append(aid)
# gross coverage per (queue, interval) ignoring breaks
gross = defaultdict(int)
for s in shifts:
    for st, en in s["segs"]:
        for u in grid:
            if st <= u < en: gross[(s["q"], u)] += 1
# surplus-rule check for breaks
for s in shifts:
    if s["hours"] < 6: continue
    first = s["segs"][0][0]
    win = [u for u in grid if 2 <= (u - first).total_seconds() / 3600 <= 5 and any(st <= u and u + timedelta(minutes=20) <= en for st, en in s["segs"])]
    if not win or len(s["brk"]) == 0: continue
    bu = s["brk"].brk.iloc[0]
    best = max(gross[(s["q"], u)] - req.get((s["q"], u), 0) for u in win)
    got = gross[(s["q"], bu.floor("30min") if False else bu)] - req.get((s["q"], bu), 0)
    if got < best: problems["break_not_max_surplus"].append((s["agent"], str(s["day"])))
# on-break per (queue, interval)
onb = defaultdict(int)
for s in shifts:
    if len(s["brk"]):
        onb[(s["q"], s["brk"].brk.iloc[0])] += 1
# attainment, both readings; hours; floors
def local_hour(u): return u.astimezone(TZ).hour + u.astimezone(TZ).minute / 60
res = {}
for q in SLA:
    ops = [u for u in grid if (8 <= local_hour(u) < 20 if q == "vip" else 6 <= local_hour(u) < 24)]
    met_op = sum(1 for u in ops if gross[(q, u)] - onb[(q, u)] >= req[(q, u)])
    pos = [u for u in ops if dem.get((q, u), (0, 0))[0] > 0]
